$user=$auth->user(); $error=null; $token=(string)($_GET['token']??$_POST['token']??'');
if($_SERVER['REQUEST_METHOD']==='POST'){
 Csrf::verify();
 try{
  $action=(string)($_POST['action']??'');
  if($action==='register'){ $user=$auth->register((string)$_POST['name'],(string)$_POST['email'],(string)$_POST['password']); redirect_to($token?'invite?token='.urlencode($token):'create-organization'); }
  if($action==='login'){ if(!$auth->login((string)$_POST['email'],(string)$_POST['password'])) throw new InvalidArgumentException('That email and password combination was not recognized.'); redirect_to($token?'invite?token='.urlencode($token):''); }
  if($action==='logout'){ $auth->logout(); redirect_to('login'); }
  if(!$user) redirect_to('login');
  if($action==='create_organization'){ $id=$repo->createOrganization((int)$user['id'],(string)$_POST['name'],(string)$_POST['organization_type'],(string)$_POST['location_name'],(string)$_POST['timezone']); $_SESSION['organization_id']=$id; flash('Your organization is ready. Build its departments and positions next.'); redirect_to('organization'); }
  if($action==='switch_organization'){ $org=$repo->organizationForUser((int)$_POST['organization_id'],(int)$user['id']); if(!$org) throw new InvalidArgumentException('You do not have access to that organization.'); $_SESSION['organization_id']=(int)$org['id']; redirect_to(); }
  if($action==='accept_invitation'){ $id=$repo->acceptInvitation($token,(int)$user['id']); $_SESSION['organization_id']=$id; flash('Invitation accepted. Welcome to the organization.'); redirect_to(); }
  $org=$repo->organizationForUser((int)($_SESSION['organization_id']??0),(int)$user['id']);
  if(!$org||!in_array($org['role'],['owner','admin'],true)) throw new InvalidArgumentException('Only owners and administrators can change organization structure.');
  $oid=(int)$org['id'];
  if($action==='add_location'){ $repo->addLocation($oid,(int)$user['id'],(string)$_POST['name']); flash('Location added.'); }
  elseif($action==='add_department'){ $repo->addDepartment($oid,(int)$user['id'],(string)$_POST['name'],(int)($_POST['location_id']??0),(string)($_POST['color']??'#2563eb')); flash('Department added.'); }
  elseif($action==='add_position'){ $repo->addPosition($oid,(int)$user['id'],(string)$_POST['name'],(int)($_POST['department_id']??0),(string)($_POST['category']??'other'),(string)($_POST['color']??'#7756d9')); flash('Custom position added.'); }
  elseif($action==='add_supervisor_group'){ $repo->addSupervisorGroup($oid,(int)$user['id'],(string)$_POST['name'],(int)($_POST['department_id']??0),(array)($_POST['supervisor_membership_ids']??[])); flash('Supervisor group added and automatic routing updated.'); }
  elseif($action==='create_invitation'){ $_SESSION['invitation_link']=$repo->createInvitation($oid,(int)$user['id'],$_POST,(string)Config::get('APP_URL',url_for())); flash('Invitation created. Copy its secure link below.'); redirect_to('team'); }
  redirect_to('organization');
 }catch(Throwable $e){ $error=$e instanceof InvalidArgumentException?$e->getMessage():'Atlas could not complete that action.'; }
}

